import{_ as t,o as s,c as a,l as o,t as i,N as r}from"./chunks/framework.Bbd9fWQx.js";const u=JSON.parse('{"title":"git-ls-remote | x-cmd man (git man1) | List references in a remote repository","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-ls-remote - List references in a remote repository","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-ls-remote | x-cmd man (git man1) | List references in a remote repository"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-ls-remote - List references in a remote repository"}]]},"headers":[],"params":{"isMan":true,"man":"git-ls-remote","category":"git man1","desc":"List references in a remote repository"},"relativePath":"git/man1/git-ls-remote.md","filePath":"git/man1/git-ls-remote.md"}'),n={name:"git/man1/git-ls-remote.md"},l={class:"visually-hidden"},h=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-ls-remote - List references in a remote repository</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls-remote</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--heads] [--tags] [--refs] [--upload-pack</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [-q </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --quiet] [--exit-code] [--get-url] [--sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [--symref] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Displays references available in a remote repository along with the associated commit IDs.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-h, --heads, -t, --tags</p><blockquote><p>Limit to only refs/heads and refs/tags, respectively. These options are <em>not</em> mutually exclusive; when given both, references stored in refs/heads and refs/tags are displayed. Note that <strong>git ls-remote -h</strong> used without anything else on the command line gives help, consistent with other git subcommands.</p></blockquote><p>--refs</p><blockquote><p>Do not show peeled tags or pseudorefs like <strong>HEAD</strong> in the output.</p></blockquote><p>-q, --quiet</p><blockquote><p>Do not print remote URL to stderr.</p></blockquote><p>--upload-pack=&lt;exec&gt;</p><blockquote><p>Specify the full path of <em>git-upload-pack</em> on the remote host. This allows listing references from repositories accessed via SSH and where the SSH daemon does not use the PATH configured by the user.</p></blockquote><p>--exit-code</p><blockquote><p>Exit with status &quot;2&quot; when no matching refs are found in the remote repository. Usually the command exits with status &quot;0&quot; to indicate it successfully talked with the remote repository, whether it found any matching refs.</p></blockquote><p>--get-url</p><blockquote><p>Expand the URL of the given remote repository taking into account any &quot;url.&lt;base&gt;.insteadOf&quot; config setting (See <strong>git-config</strong>(1)) and exit without talking to the remote.</p></blockquote><p>--symref</p><blockquote><p>In addition to the object pointed by it, show the underlying ref pointed by it when showing a symbolic ref. Currently, upload-pack only shows the symref HEAD, so it will be the only one shown by ls-remote.</p></blockquote><p>--sort=&lt;key&gt;</p><blockquote><p>Sort based on the key given. Prefix <strong>-</strong> to sort in descending order of the value. Supports &quot;version:refname&quot; or &quot;v:refname&quot; (tag names are treated as versions). The &quot;version:refname&quot; sort order can also be affected by the &quot;versionsort.suffix&quot; configuration variable. See <strong>git-for-each-ref</strong>(1) for more sort options, but be aware keys like <strong>committerdate</strong> that require access to the objects themselves will not work for refs whose objects have not yet been fetched from the remote, and will give a <strong>missing object</strong> error.</p></blockquote><p>-o &lt;option&gt;, --server-option=&lt;option&gt;</p><blockquote><p>Transmit the given string to the server when communicating using protocol version 2. The given string must not contain a NUL or LF character. When multiple <strong>--server-option=&lt;option&gt;</strong> are given, they are all sent to the other side in the order listed on the command line.</p></blockquote><p>&lt;repository&gt;</p><blockquote><p>The &quot;remote&quot; repository to query. This parameter can be either a URL or the name of a remote (see the GIT URLS and REMOTES sections of <strong>git-fetch</strong>(1)).</p></blockquote><p>&lt;patterns&gt;...</p><blockquote><p>When unspecified, all references, after filtering done with --heads and --tags, are shown. When &lt;patterns&gt;... are specified, only references matching one or more of the given patterns are displayed. Each pattern is interpreted as a glob (see <strong>glob</strong> in <strong>gitglossary</strong>(7)) which is matched against the &quot;tail&quot; of a ref, starting either from the start of the ref (so a full name like <strong>refs/heads/foo</strong> matches) or from a slash separator (so <strong>bar</strong> matches <strong>refs/heads/bar</strong> but not <strong>refs/heads/foobar</strong>).</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><blockquote><pre><code>$ git ls-remote --tags .
d6602ec5194c87b0fc87103ca4d67251c76f233a        refs/tags/v0.99
f25a265a342aed6041ab0cc484224d9ca54b6f41        refs/tags/v0.99.1
7ceca275d047c90c0c7d5afb13ab97efdf51bd6e        refs/tags/v0.99.3
c5db5456ae3b0873fc659c19fafdde22313cc441        refs/tags/v0.99.2
0918385dbd9656cab0d1d81ba7453d49bbc16250        refs/tags/junio-gpg-pub

$ git ls-remote http://www.kernel.org/pub/scm/git/git.git master seen rc
5fe978a5381f1fbad26a80e682ddd2a401966740        refs/heads/master
c781a84b5204fb294c9ccc79f8b3baceeb32c061        refs/heads/seen

$ git remote add korg http://www.kernel.org/pub/scm/git/git.git
$ git ls-remote --tags korg v\\*
d6602ec5194c87b0fc87103ca4d67251c76f233a        refs/tags/v0.99
f25a265a342aed6041ab0cc484224d9ca54b6f41        refs/tags/v0.99.1
c5db5456ae3b0873fc659c19fafdde22313cc441        refs/tags/v0.99.2
7ceca275d047c90c0c7d5afb13ab97efdf51bd6e        refs/tags/v0.99.3
</code></pre></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-check-ref-format</strong>(1).</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,35);function c(e,p,g,d,m,f){return s(),a("div",null,[o("h1",l,i(e.$params.man),1),h])}const b=t(n,[["render",c]]);export{u as __pageData,b as default};
